<script setup>
import { computed, reactive, ref } from 'vue'; import MButton from '../../../components/mds/MButton.vue'; import MDialog from '../../../components/mds/MDialog.vue'; import MInput from '../../../components/mds/MInput.vue'; import MMobileTopBar from '../../../components/mds/MMobileTopBar.vue'; import MSelect from '../../../components/mds/MSelect.vue'; import MTextarea from '../../../components/mds/MTextarea.vue'; import { toInteractionCreateDraft, toInteractionCreatePayload } from '../domain/interaction-write.mjs';
const props = defineProps({ partner: { type: Object, default: null }, results: { type: Array, default: () => [] }, searching: { type: Boolean, default: false }, saving: { type: Boolean, default: false }, serverError: { type: String, default: '' }, safeAreaStyle: { type: Object, default: () => ({}) } }); const emit = defineEmits(['cancel', 'search', 'select', 'save']); const draft = reactive({ ...toInteractionCreateDraft() }); const partnerQuery = ref(''); const localError = ref(''); const discard = ref(false); const initialDraft = JSON.stringify(draft); const channels = ['', 'Gặp trực tiếp', 'Điện thoại', 'Email', 'Zalo', 'Khác'].map((value) => ({ value, label: value || 'Chọn kênh' })); const results = ['', 'Tốt', 'Đang theo dõi', 'Chưa đạt'].map((value) => ({ value, label: value || 'Chọn kết quả' })); const dirty = computed(() => JSON.stringify(draft) !== initialDraft || partnerQuery.value !== '');
function find() { emit('search', partnerQuery.value.trim()); } function requestCancel() { if (props.saving) return; if (dirty.value) { discard.value = true; return; } emit('cancel'); } function submit() { try { localError.value = ''; emit('save', toInteractionCreatePayload(draft, props.partner)); } catch (error) { localError.value = error.message; } }
</script>
<template><section class="mds-mobile-app flex h-[100dvh] min-w-0 flex-col overflow-hidden bg-[var(--mds-bg)]" :style="safeAreaStyle"><MMobileTopBar title="Ghi nhận tương tác" @back="requestCancel"><template #actions><MButton variant="link" :disabled="saving" @click="requestCancel">Hủy</MButton></template></MMobileTopBar><form class="flex min-h-0 flex-1 flex-col" novalidate @submit.prevent="submit"><div class="min-h-0 flex-1 overflow-y-auto"><div class="mds-mobile-gutter-x space-y-4 py-4"><section><span class="mb-1.5 block text-[13px] font-medium">Đối tác <span class="text-[var(--mds-danger)]">*</span></span><div class="flex gap-2"><MInput v-model="partnerQuery" placeholder="Tìm đối tác…" :disabled="saving" @change="find" /><MButton variant="neutral" :loading="searching" @click="find">Tìm</MButton></div><div v-if="results.length" class="mt-2 divide-y divide-[var(--mds-border-light)] rounded-lg border border-[var(--mds-border-light)]"><MButton v-for="item in results" :key="`${item.type}-${item.id}`" variant="link" class="flex w-full justify-start px-3 py-2 text-left" @click="emit('select', item)"><span><strong>{{ item.name }}</strong><span class="ml-2 text-[12px] text-[var(--mds-text-secondary)]">{{ item.sub }}</span></span></MButton></div><p v-if="partner" class="mt-2 rounded-lg bg-[var(--mds-brand-50)] px-3 py-2 text-[13px] text-[var(--mds-brand-700)]">Đã chọn: <strong>{{ partner.name }}</strong></p></section><label><span class="mb-1.5 block text-[13px] font-medium">Ngày <span class="text-[var(--mds-danger)]">*</span></span><MInput v-model="draft.date" type="date" :disabled="saving" /></label><label><span class="mb-1.5 block text-[13px] font-medium">Kênh</span><MSelect v-model="draft.channel" :options="channels" :disabled="saving" /></label><label><span class="mb-1.5 block text-[13px] font-medium">Kết quả</span><MSelect v-model="draft.result" :options="results" :disabled="saving" /></label><label><span class="mb-1.5 block text-[13px] font-medium">Người thực hiện</span><MInput v-model="draft.staff" :disabled="saving" /></label><label><span class="mb-1.5 block text-[13px] font-medium">Nội dung</span><MTextarea v-model="draft.summary" placeholder="Ghi nhận nội dung trao đổi" :disabled="saving" /></label><p v-if="localError || serverError" role="alert" class="rounded-lg bg-[var(--mds-danger-bg)] px-3 py-2 text-[13px] text-[var(--mds-danger)]">{{ localError || serverError }}</p></div></div><footer class="shrink-0 border-t border-[var(--mds-border-light)] bg-[var(--mds-bg)] px-4 pb-[calc(12px+var(--mds-mobile-safe-bottom))] pt-3"><MButton variant="primary" class="w-full" :loading="saving" :disabled="saving" @click="submit">Lưu tương tác</MButton></footer></form><MDialog v-model="discard" title="Bỏ tương tác mới?" type="danger" confirm-text="Bỏ thay đổi" @confirm="emit('cancel')"><p>Thông tin chưa lưu sẽ không được giữ lại.</p></MDialog></section></template>
